-- supabase/migrations/20261122d_sync_dev_menu_items_data.sql
-- 把 dev 的 menu_items 整張表內容（名稱、價格、分類、圖片、庫存連動設定等）
-- 用 prod 的資料覆蓋，確保兩邊菜單完全一致。dev 原本 66 筆品項全部都在 prod
-- 裡（id 一致），prod 多出 9 筆 dev 沒有的品項，一併補上。

begin;

on conflict (id) do update set
  name = excluded.name,
  print_name = excluded.print_name,
  price = excluded.price,
  category = excluded.category,
  sort_order = excluded.sort_order,
  stock = excluded.stock,
  sold_out = excluded.sold_out,
  consumes = excluded.consumes,
  image_url = excluded.image_url,
  created_at = excluded.created_at,
  thresholds = excluded.thresholds,
  customer_print_name = excluded.customer_print_name;

commit;
